import Foundation

@main enum SystemKeyboardFocusTests {
    static func main() {
        var count = 0
        func check(_ name: String, _ value: Bool) { precondition(value, name); count += 1; print("PASS \(name)") }
        let protected: [Int32] = [20, 30]
        var state = SystemKeyboardFocusState(focus: .regularApp(10))
        check("ordinary application activation is not suppressed", !state.keyFocusTaken(thiefPID: 40, thief: .regularApp(40), victimPID: 10, protectedApps: protected))
        check("protected app cannot steal focus from another app", state.keyFocusTaken(thiefPID: 20, thief: .regularApp(20), victimPID: 10, protectedApps: protected))
        check("the suppression records actual thief and victim", state.suppression?.thiefPID == 20 && state.suppression?.victimPID == 10)
        check("foreign input addressed to the thief returns to its victim", state.keyboardRecipient(sourcePID: 90, targetPID: 20, servicePID: 99) == 10)
        check("service input reaches the synthetic receiver", state.keyboardRecipient(sourcePID: 99, targetPID: 20, servicePID: 99) == nil)
        check("input addressed to another app is unaffected", state.keyboardRecipient(sourcePID: 90, targetPID: 30, servicePID: 99) == nil)
        check("overflowing source PID is not redirected", state.keyboardRecipient(sourcePID: Int64.max, targetPID: 20, servicePID: 99) == nil)
        check("unrelated return is delivered", !state.keyFocusReturned(to: 30))
        check("the first victim return is suppressed", state.keyFocusReturned(to: 10))
        check("a repeated victim return is delivered", !state.keyFocusReturned(to: 10))
        let changed = state.focusChanged(to: .regularApp(20), rawPID: 20, protectedApps: protected)
        check("suppressed thief does not receive a gained callback", changed.notifications.isEmpty)
        check("focus change to thief requests release", changed.releaseTheft)
        check("observed focus and previous focus are kept independently", state.currentFocus == .regularApp(20) && state.previousFocus == .regularApp(10))
        state.completed(changed, releasedFocus: true)
        check("regular changes do not overwrite view-bridge suppression", !state.lastViewBridgeFocusStealWasSuppressed)
        let repeated = state.focusChanged(to: .regularApp(20), rawPID: 20, protectedApps: protected)
        check("the same theft is released only once", !repeated.releaseTheft && repeated.notifications.isEmpty)
        let returned = state.focusChanged(to: .regularApp(10), rawPID: 10, protectedApps: protected)
        check("released thief receives its later lost callback", returned.notifications == [.lost(20)])
        check("returning to victim retains suppression until new-front", state.suppression != nil)
        check("an unrelated new-front preserves the recorded theft", !state.newFront(focusPID: 30) && state.suppression != nil)
        check("thief new-front clears the recorded theft", !state.newFront(focusPID: 20) && state.suppression == nil)
        var ordinary = SystemKeyboardFocusState(focus: .regularApp(20))
        check("the already-focused protected app is allowed", !ordinary.keyFocusTaken(thiefPID: 20, thief: .regularApp(20), victimPID: 20, protectedApps: protected))
        let swap = ordinary.focusChanged(to: .regularApp(30), rawPID: 30, protectedApps: protected)
        check("real focus changes report loss and gain", swap.notifications == [.lost(20), .gained(30)])
        var ordered = SystemKeyboardFocusState(focus: .regularApp(20))
        let registered = ordered.focusChanged(to: .regularApp(30), rawPID: 30, protectedApps: [30, 20, 30])
        check("callbacks preserve registration order and duplicate registrations", registered.notifications == [.gained(30), .lost(20), .gained(30)])
        var hosted = SystemKeyboardFocusState(focus: .viewService(appPID: 10, servicePID: nil))
        check("hosted theft uses the mapped app for protection", hosted.keyFocusTaken(thiefPID: 200, thief: .viewService(appPID: 20, servicePID: 200), victimPID: 10, protectedApps: protected))
        check("hosted keyboard routes from the actual thief PID", hosted.keyboardRecipient(sourcePID: 90, targetPID: 200, servicePID: 99) == 10 && hosted.keyboardRecipient(sourcePID: 90, targetPID: 20, servicePID: 99) == nil)
        let hostChange = hosted.focusChanged(to: .viewService(appPID: 20, servicePID: nil), rawPID: 200, protectedApps: protected)
        check("hosted thief is released without duplicate AX inspection", hostChange.releaseTheft && !hostChange.inspectViewService)
        hosted.completed(hostChange, releasedFocus: true)
        check("successful unknown-service release suppresses bridge new-front", hosted.lastViewBridgeFocusStealWasSuppressed && hosted.newFront(focusPID: 200))
        let stableHost = hosted.focusChanged(to: .viewService(appPID: 20, servicePID: 201), rawPID: 201, protectedApps: protected)
        hosted.completed(stableHost, releasedFocus: false)
        check("same mapped host has no spurious focus callback", stableHost.notifications.isEmpty)
        check("known-service changes preserve bridge suppression state", hosted.lastViewBridgeFocusStealWasSuppressed)
        let next = hosted.focusChanged(to: .viewService(appPID: 30, servicePID: nil), rawPID: 300, protectedApps: protected)
        hosted.completed(next, releasedFocus: false)
        check("unknown-service non-release resets bridge suppression", !hosted.lastViewBridgeFocusStealWasSuppressed)
        var unresolved = SystemKeyboardFocusState(focus: .viewService(appPID: 10, servicePID: nil))
        let uncertain = unresolved.focusChanged(to: .viewService(appPID: 20, servicePID: nil), rawPID: 200, protectedApps: protected)
        check("cross-host unknown service requests the native AX recovery branch", uncertain.inspectViewService && !uncertain.releaseTheft)
        var third = SystemKeyboardFocusState(focus: .regularApp(10))
        _ = third.keyFocusTaken(thiefPID: 20, thief: .regularApp(20), victimPID: 10, protectedApps: protected)
        _ = third.focusChanged(to: .regularApp(40), rawPID: 40, protectedApps: protected)
        check("a third focus owner discards obsolete suppression", third.suppression == nil)
        _ = third.keyFocusTaken(thiefPID: 20, thief: .regularApp(20), victimPID: 40, protectedApps: protected)
        _ = third.keyFocusTaken(thiefPID: 50, thief: .regularApp(50), victimPID: 40, protectedApps: protected)
        check("allowed subsequent take discards prior suppression", third.suppression == nil)
        print("ALL \(count) SYSTEM KEYBOARD FOCUS STATE CHECKS PASSED; persistent native adapter not exercised")
    }
}
